use std::{
    ffi::{CStr, CString},
    fs::File,
    io::{self, Read},
    process,
    sync::{Arc, Mutex},
};

use libc::{EINVAL, c_long, c_ulong, c_void, syscall, uid_t};
use std::{mem::MaybeUninit, thread::sleep, time::{Duration, Instant}};
use log::{error, info, warn};

use crate::package::{read_ap_package_config, synchronize_package_uid};

// Generated by build.rs from app/src/main/cpp/version (single source of the
// KernelPatch version embedded into supercalls).
include!(concat!(env!("OUT_DIR"), "/kp_version.rs"));

const KSTORAGE_EXCLUDE_LIST_GROUP: i32 = 1;

// AArch32 (armeabi-v7a) needs a different entry: nr45 in the native arm32
// sys_call_table is sys_brk, so the daemon would be performing a brk() and never
// reach the KernelPatch supercall hook.  This must match the kernel side
// (uapi/scdefs.h, CONFIG_ARM) and the app's copy of the same header; on the XTC
// 4.9/arm32 kernel slot 394 is sys_pkey_mprotect, a syscall that never runs on
// arm32/Android (the unused sys_ni_syscall slots there are 388/389/399).
#[cfg(target_arch = "arm")]
const __NR_SUPERCALL: c_long = 394;
#[cfg(not(target_arch = "arm"))]
const __NR_SUPERCALL: c_long = 45;
const SUPERCALL_SU: c_long = 0x1010;
const SUPERCALL_KSTORAGE_WRITE: c_long = 0x1041;
const SUPERCALL_KSTORAGE_READ: c_long = 0x1042;
const SUPERCALL_SU_GRANT_UID: c_long = 0x1100;
const SUPERCALL_SU_REVOKE_UID: c_long = 0x1101;
const SUPERCALL_SU_NUMS: c_long = 0x1102;
const SUPERCALL_SU_LIST: c_long = 0x1103;
const SUPERCALL_SU_RESET_PATH: c_long = 0x1111;
const SUPERCALL_SU_GET_SAFEMODE: c_long = 0x1112;
const SUPERCALL_SU_PENDING_POLL: c_long = 0x1113;
const SUPERCALL_SU_DECISION: c_long = 0x1114;

const KSTORAGE_SU_PROMPT_GROUP: i32 = 2;
const SU_DECISION_PENDING: i32 = 0;
const SU_DECISION_ALLOW: i32 = 1;
const SU_DECISION_DENY: i32 = -1;
const SU_DECISION_TIMEOUT: i32 = -2;
const SU_PROMPT_TIMEOUT_SECS: u64 = 60;

const SUPERCALL_SCONTEXT_LEN: usize = 0x60;

#[repr(C)]
struct SuRequest {
    uid: u32,          // uid_t == unsigned int, but keep 4-byte field distinct
    to_uid: u32,
    pid: i32,
    stamp: c_ulong,
    decision: i32,
    scontext: [u8; SUPERCALL_SCONTEXT_LEN],
    comm: [u8; 16],
}

#[repr(C)]
struct SuProfile {
    uid: i32,
    to_uid: i32,
    scontext: [u8; SUPERCALL_SCONTEXT_LEN],
}

fn ver_and_cmd(cmd: c_long) -> c_long {
    let version_code: u32 = ((KP_MAJOR << 16) + (KP_MINOR << 8) + KP_PATCH)
        .try_into()
        .unwrap();
    // AArch32: c_long is 32 bits, so the KernelPatch version cannot be packed
    // into the high half of the word -- `<< 32` is a const-eval overflow and is
    // rejected outright (#[deny(arithmetic_overflow)]).  The kernel only decodes
    // `cmd = ver_xx_cmd & 0xFFFF` (the version lives in bits 32.. where it is
    // ignored, "todo: from 0.10.5"), so dropping it is lossless on arm32.
    #[cfg(target_pointer_width = "64")]
    {
        ((version_code as c_long) << 32) | (0x1158 << 16) | (cmd & 0xFFFF)
    }
    #[cfg(target_pointer_width = "32")]
    {
        (0x1158 << 16) | (cmd & 0xFFFF)
    }
}

fn sc_su_revoke_uid(key: &CStr, uid: uid_t) -> c_long {
    if key.to_bytes().is_empty() {
        return (-EINVAL).into();
    }
    unsafe {
        syscall(
            __NR_SUPERCALL,
            key.as_ptr(),
            ver_and_cmd(SUPERCALL_SU_REVOKE_UID),
            uid,
        ) as c_long
    }
}

fn sc_su_grant_uid(key: &CStr, profile: &SuProfile) -> c_long {
    if key.to_bytes().is_empty() {
        return (-EINVAL).into();
    }
    unsafe {
        syscall(
            __NR_SUPERCALL,
            key.as_ptr(),
            ver_and_cmd(SUPERCALL_SU_GRANT_UID),
            profile,
        ) as c_long
    }
}

fn sc_kstorage_write(
    key: &CStr,
    gid: i32,
    did: i64,
    data: *mut c_void,
    offset: i32,
    dlen: i32,
) -> c_long {
    if key.to_bytes().is_empty() {
        return (-EINVAL).into();
    }
    unsafe {
        syscall(
            __NR_SUPERCALL,
            key.as_ptr(),
            ver_and_cmd(SUPERCALL_KSTORAGE_WRITE),
            gid as c_long,
            did as c_long,
            data,
            (((offset as i64) << 32) | (dlen as i64)) as c_long,
        ) as c_long
    }
}

fn sc_set_ap_mod_exclude(key: &CStr, uid: i64, exclude: i32) -> c_long {
    sc_kstorage_write(
        key,
        KSTORAGE_EXCLUDE_LIST_GROUP,
        uid,
        &exclude as *const i32 as *mut c_void,
        0,
        size_of::<i32>() as i32,
    )
}

pub fn sc_su_get_safemode(key: &CStr) -> c_long {
    if key.to_bytes().is_empty() {
        warn!("[sc_su_get_safemode] null superkey, tell apd we are not in safemode!");
        return 0;
    }

    let key_ptr = key.as_ptr();
    if key_ptr.is_null() {
        warn!("[sc_su_get_safemode] superkey pointer is null!");
        return 0;
    }

    unsafe {
        syscall(
            __NR_SUPERCALL,
            key_ptr,
            ver_and_cmd(SUPERCALL_SU_GET_SAFEMODE),
        ) as c_long
    }
}

fn sc_su(key: &CStr, profile: &SuProfile) -> c_long {
    if key.to_bytes().is_empty() {
        return (-EINVAL).into();
    }
    unsafe {
        syscall(
            __NR_SUPERCALL,
            key.as_ptr(),
            ver_and_cmd(SUPERCALL_SU),
            profile,
        ) as c_long
    }
}

fn sc_su_reset_path(key: &CStr, path: &CStr) -> c_long {
    if key.to_bytes().is_empty() || path.to_bytes().is_empty() {
        return (-EINVAL).into();
    }
    unsafe {
        syscall(
            __NR_SUPERCALL,
            key.as_ptr(),
            ver_and_cmd(SUPERCALL_SU_RESET_PATH),
            path.as_ptr(),
        ) as c_long
    }
}

fn sc_su_uid_nums(key: &CStr) -> c_long {
    if key.to_bytes().is_empty() {
        return (-EINVAL).into();
    }
    unsafe { syscall(__NR_SUPERCALL, key.as_ptr(), ver_and_cmd(SUPERCALL_SU_NUMS)) as c_long }
}

fn sc_su_allow_uids(key: &CStr, buf: &mut [uid_t]) -> c_long {
    if key.to_bytes().is_empty() {
        return (-EINVAL).into();
    }
    if buf.is_empty() {
        return (-EINVAL).into();
    }
    unsafe {
        syscall(
            __NR_SUPERCALL,
            key.as_ptr(),
            ver_and_cmd(SUPERCALL_SU_LIST),
            buf.as_mut_ptr(),
            buf.len() as i32,
        ) as c_long
    }
}

fn read_file_to_string(path: &str) -> io::Result<String> {
    let mut file = File::open(path)?;
    let mut content = String::new();
    file.read_to_string(&mut content)?;
    Ok(content)
}

fn convert_string_to_u8_array(s: &str) -> [u8; SUPERCALL_SCONTEXT_LEN] {
    let mut u8_array = [0u8; SUPERCALL_SCONTEXT_LEN];
    let bytes = s.as_bytes();
    let len = usize::min(SUPERCALL_SCONTEXT_LEN, bytes.len());
    u8_array[..len].copy_from_slice(&bytes[..len]);
    u8_array
}

fn convert_superkey(s: &Option<String>) -> Option<CString> {
    s.as_ref().and_then(|s| CString::new(s.clone()).ok())
}

fn sc_kstorage_read(key: &CStr, gid: i32, did: i64, data: *mut c_void, dlen: i32) -> c_long {
    if key.to_bytes().is_empty() {
        return (-EINVAL).into();
    }
    unsafe {
        syscall(
            __NR_SUPERCALL,
            key.as_ptr(),
            ver_and_cmd(SUPERCALL_KSTORAGE_READ),
            gid as c_long,
            did as c_long,
            data,
            (((0i64) << 32) | (dlen as i64)) as c_long,
        ) as c_long
    }
}

/// Block (in userspace, where sleeping is legal) until the trusted manager
/// writes a decision for our pending su request, then report ALLOW/DENY.
/// The kernel only records the request; it never waits.
pub fn await_su_decision(superkey: &Option<String>) -> bool {
    let key = match convert_superkey(superkey) {
        Some(k) => k,
        // The kernel executes su without injecting a superkey argument, so the
        // argv-derived key is usually absent or a dummy. kstorage reads are
        // performed before the kernel's is_authed gate (supercall.c), i.e. they
        // need only a non-empty key, not the real credential. Fall back to the
        // literal "su" instead of failing closed, otherwise every keyless `su`
        // (including whitelisted callers with no pending record) is refused.
        None => CString::new("su").unwrap(),
    };
    let pid = process::id() as i64;

    // Only arbitrate when a pending record actually exists for us (the kernel
    // writes one only when su_prompt is enabled and the uid is not whitelisted).
    let mut req = MaybeUninit::<SuRequest>::uninit();
    let rc = sc_kstorage_read(
        &key,
        KSTORAGE_SU_PROMPT_GROUP,
        pid,
        req.as_mut_ptr() as *mut c_void,
        size_of::<SuRequest>() as i32,
    );
    if rc < 0 {
        // No pending record -> normal whitelisted su, proceed without prompt.
        return true;
    }
    let mut req = unsafe { req.assume_init() };
    if req.decision != SU_DECISION_PENDING {
        return req.decision == SU_DECISION_ALLOW;
    }

    info!("[su_prompt] waiting for decision, pid={}, uid={}", pid, req.uid);
    let start = Instant::now();
    loop {
        sleep(Duration::from_millis(100));
        let mut cur = MaybeUninit::<SuRequest>::uninit();
        let r = sc_kstorage_read(
            &key,
            KSTORAGE_SU_PROMPT_GROUP,
            pid,
            cur.as_mut_ptr() as *mut c_void,
            size_of::<SuRequest>() as i32,
        );
        if r < 0 {
            // Record vanished (e.g. manager removed it) -> deny.
            warn!("[su_prompt] pending record vanished, denying");
            return false;
        }
        let cur = unsafe { cur.assume_init() };
        if cur.decision == SU_DECISION_ALLOW {
            info!("[su_prompt] ALLOW pid={}", pid);
            return true;
        }
        if cur.decision == SU_DECISION_DENY {
            info!("[su_prompt] DENY pid={}", pid);
            return false;
        }
        if start.elapsed() >= Duration::from_secs(SU_PROMPT_TIMEOUT_SECS) {
            warn!("[su_prompt] timeout pid={}", pid);
            return false;
        }
    }
}

pub fn refresh_ap_package_list(skey: &CStr, mutex: &Arc<Mutex<()>>) {
    let _lock = mutex.lock().unwrap();

    let num = sc_su_uid_nums(skey);
    if num < 0 {
        error!("[refresh_su_list] Error getting number of UIDs: {}", num);
        return;
    }
    let num = num as usize;
    let mut uids = vec![0 as uid_t; num];
    let n = sc_su_allow_uids(skey, &mut uids);
    if n < 0 {
        error!("[refresh_su_list] Error getting su list");
        return;
    }
    for uid in &uids {
        if *uid == 0 || *uid == 2000 {
            warn!(
                "[refresh_ap_package_list] Skip revoking critical uid: {}",
                uid
            );
            continue;
        }
        info!(
            "[refresh_ap_package_list] Revoking {} root permission...",
            uid
        );
        let rc = sc_su_revoke_uid(skey, *uid);
        if rc != 0 {
            error!("[refresh_ap_package_list] Error revoking UID: {}", rc);
        }
    }

    if let Err(e) = synchronize_package_uid() {
        error!("Failed to synchronize package UIDs: {}", e);
    }

    let package_configs = read_ap_package_config();
    for config in package_configs {
        if config.allow == 1 && config.exclude == 0 {
            let profile = SuProfile {
                uid: config.uid,
                to_uid: config.to_uid,
                scontext: convert_string_to_u8_array(&config.sctx),
            };
            let result = sc_su_grant_uid(skey, &profile);
            info!(
                "[refresh_ap_package_list] Loading {}: result = {}",
                config.pkg, result
            );
        }
        if config.allow == 0 && config.exclude == 1 {
            let result = sc_set_ap_mod_exclude(skey, config.uid as i64, 1);
            info!(
                "[refresh_ap_package_list] Loading exclude {}: result = {}",
                config.pkg, result
            );
        }
    }
}

pub fn privilege_apd_profile(superkey: &Option<String>) {
    let key = convert_superkey(superkey);

    let all_allow_ctx = "u:r:magisk:s0";
    let profile = SuProfile {
        uid: process::id().try_into().expect("PID conversion failed"),
        to_uid: 0,
        scontext: convert_string_to_u8_array(all_allow_ctx),
    };
    if let Some(ref key) = key {
        let result = sc_su(key, &profile);
        info!("[privilege_apd_profile] result = {}", result);
    }
}

pub fn init_load_su_path(superkey: &Option<String>) {
    let su_path_file = "/data/adb/ap/su_path";

    match read_file_to_string(su_path_file) {
        Ok(su_path) => {
            let superkey_cstr = convert_superkey(superkey);

            match superkey_cstr {
                Some(superkey_cstr) => match CString::new(su_path.trim()) {
                    Ok(su_path_cstr) => {
                        let result = sc_su_reset_path(&superkey_cstr, &su_path_cstr);
                        if result == 0 {
                            info!("suPath load successfully");
                        } else {
                            warn!("Failed to load su path, error code: {}", result);
                        }
                    }
                    Err(e) => {
                        warn!("Failed to convert su_path: {}", e);
                    }
                },
                _ => {
                    warn!("Superkey is None, skipping...");
                }
            }
        }
        Err(e) => {
            warn!("Failed to read su_path file: {}", e);
        }
    }
}
